import { gsap } from 'gsap';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uniform, color, vec3, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.position.copy(config.scenePosition || new THREE.Vector3());

  const timelines = [];
  const cleanups = [];

  // ─────────────────────────────────────────────────────────────
  // 1. BACKDROP GRADIENT PLANE (7x6 units at z=-2.5)
  // ─────────────────────────────────────────────────────────────
  const backdropGeometry = new THREE.PlaneGeometry(7, 6);
  const gradientStops = config.intent?.visualSpec?.colors?.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  // Build vertical gradient as a canvas texture
  const canvas = document.createElement('canvas');
  canvas.width = 1;
  canvas.height = 256;
  const ctx2d = canvas.getContext('2d');
  const gradient = ctx2d.createLinearGradient(0, 0, 0, 256);
  for (const stop of gradientStops) {
    gradient.addColorStop(stop.at, stop.hex);
  }
  ctx2d.fillStyle = gradient;
  ctx2d.fillRect(0, 0, 1, 256);

  const gradientTexture = new THREE.CanvasTexture(canvas);
  gradientTexture.magFilter = THREE.LinearFilter;
  gradientTexture.minFilter = THREE.LinearFilter;

  const backdropMaterial = new THREE.MeshBasicMaterial({
    map: gradientTexture,
    toneMapped: false,
  });
  const backdropMesh = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdropMesh.position.z = -2.5;
  group.add(backdropMesh);

  // ─────────────────────────────────────────────────────────────
  // 2. CONTACT SHADOW PLANE (radial gradient under plinth)
  // ─────────────────────────────────────────────────────────────
  const shadowCanvas = document.createElement('canvas');
  shadowCanvas.width = 256;
  shadowCanvas.height = 256;
  const shadowCtx = shadowCanvas.getContext('2d');
  shadowCtx.fillStyle = '#000000';
  shadowCtx.fillRect(0, 0, 256, 256);

  const shadowGradient = shadowCtx.createRadialGradient(128, 128, 0, 128, 128, 128);
  shadowGradient.addColorStop(0, 'rgba(0,0,0,0.55)');
  shadowGradient.addColorStop(1, 'rgba(0,0,0,0)');
  shadowCtx.fillStyle = shadowGradient;
  shadowCtx.fillRect(0, 0, 256, 256);

  const shadowTexture = new THREE.CanvasTexture(shadowCanvas);
  const shadowGeometry = new THREE.PlaneGeometry(3.2, 3.2);
  const shadowMaterial = new THREE.MeshBasicMaterial({
    map: shadowTexture,
    transparent: true,
    toneMapped: false,
  });
  const shadowMesh = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadowMesh.position.set(0, -1.1, 0.05);
  group.add(shadowMesh);

  // ─────────────────────────────────────────────────────────────
  // 3. PLINTH (low cylindrical base)
  // ─────────────────────────────────────────────────────────────
  const plinthGeometry = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMaterial = new MeshStandardNodeMaterial();
  plinthMaterial.colorNode = uniform(color(new THREE.Color('#14141a')));
  plinthMaterial.roughnessNode = uniform(0.7);
  plinthMaterial.metalnessNode = uniform(0.3);
  plinthMaterial.side = THREE.FrontSide;

  const plinthMesh = new THREE.Mesh(plinthGeometry, plinthMaterial);
  plinthMesh.position.y = -1.1;
  group.add(plinthMesh);

  // ─────────────────────────────────────────────────────────────
  // 4. WATCH MESH (load GLB and apply PBR)
  // ─────────────────────────────────────────────────────────────
  const watchGroup = new THREE.Group();
  watchGroup.position.set(0, 0, 0);
  group.add(watchGroup);

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene;

    // Scale watch to 2.2 scene units tall
    const bbox = new THREE.Box3().setFromObject(scene);
    const height = bbox.max.y - bbox.min.y;
    const scale = height > 0 ? 2.2 / height : 1;
    scene.scale.multiplyScalar(scale);

    // Center at origin
    bbox.setFromObject(scene);
    const center = bbox.getCenter(new THREE.Vector3());
    scene.position.sub(center);

    // Apply machined-metal PBR to all meshes
    scene.traverse((node) => {
      if (node.isMesh) {
        const mat = new MeshStandardNodeMaterial();
        mat.colorNode = uniform(color(new THREE.Color(0xcccccc))); // Neutral base for brushed metal
        mat.roughnessNode = uniform(0.52);
        mat.metalnessNode = uniform(0.55);
        mat.clearcoatNode = uniform(0.2);
        mat.clearcoatRoughnessNode = uniform(0.4);
        mat.anisotropyNode = uniform(0.8);
        mat.side = THREE.FrontSide;
        node.material = mat;
      }
    });

    watchGroup.add(scene);
  });

  // ─────────────────────────────────────────────────────────────
  // 5. LIGHTING SETUP
  // ─────────────────────────────────────────────────────────────

  // Ambient fill
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
  group.add(ambientLight);

  // Key light (main illumination)
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(3, 2, 3);
  keyLight.castShadow = false;
  group.add(keyLight);

  // Rim light (left case edge, accent red)
  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-3, 1.5, 2);
  group.add(rimLight);

  // ─────────────────────────────────────────────────────────────
  // 6. TYPOGRAPHY (text content)
  // ─────────────────────────────────────────────────────────────
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Parse text items
  let headlineText = 'Calibre NA-01';
  let bodyText = 'Machined in-house. 41 mm. Grade 5 titanium.';
  let captionText = 'FROM 4200 USD / SHIPS IN 21 DAYS';

  for (const item of items) {
    if (item.role === 'headline' || item.typography?.fontSize === 68) {
      headlineText = item.text || item.content || headlineText;
    } else if (item.typography?.fontSize === 26) {
      bodyText = item.text || item.content || bodyText;
    } else if (item.typography?.fontSize === 18) {
      captionText = item.text || item.content || captionText;
    }
  }

  // Headline: 1.5 units (6x base 0.25) below scene center
  const headlineObj = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
  });
  headlineObj.position.set(0, -1.5, 0.1);
  group.add(headlineObj);

  // Body: 0.5 units (2x base) below headline
  const bodyObj = ctx.fontAtlas.createText(bodyText, {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'center',
  });
  bodyObj.position.set(0, -2.0, 0.1);
  group.add(bodyObj);

  // Caption: 0.5 units (2x base) below body
  const captionObj = ctx.fontAtlas.createText(captionText, {
    fontSize: 18,
    color: '#ff2a38',
    align: 'center',
    letterSpacingPx: 2,
  });
  captionObj.position.set(0, -2.5, 0.1);
  group.add(captionObj);

  // ─────────────────────────────────────────────────────────────
  // 7. CINEMATIC PRIMITIVES
  // ─────────────────────────────────────────────────────────────

  // Orbit: load trigger, rotates watch group about y at 0.15 rad/s, radius 0.6
  const orbitResult = ctx.primitives['orbit'](watchGroup, {
    speed: 0.15,
    radius: 0.6,
  });
  if (orbitResult) {
    cleanups.push(() => orbitResult.cleanup?.());
    if (orbitResult.timeline) timelines.push(orbitResult.timeline);
  }

  // Depth-rotate: hover trigger, tilt up to 6 deg toward cursor over 300ms
  const depthRotateResult = ctx.primitives['depth-rotate'](watchGroup, {
    maxDeg: 6,
  });
  if (depthRotateResult) {
    cleanups.push(() => depthRotateResult.cleanup?.());
    if (depthRotateResult.timeline) timelines.push(depthRotateResult.timeline);
  }

  // ─────────────────────────────────────────────────────────────
  // 8. EVENT HANDLERS & CLEANUP
  // ─────────────────────────────────────────────────────────────

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach((tl) => {
      if (tl && tl.kill) tl.kill();
    });

    // Execute cleanup callbacks
    cleanups.forEach((fn) => {
      if (fn) fn();
    });

    // Dispose materials and geometries
    backdropGeometry.dispose();
    backdropMaterial.dispose();
    gradientTexture.dispose();

    shadowGeometry.dispose();
    shadowMaterial.dispose();
    shadowTexture.dispose();

    plinthGeometry.dispose();
    plinthMaterial.dispose();

    ambientLight.dispose?.();
    keyLight.dispose?.();
    rimLight.dispose?.();
  };

  return group;
}
